// ESM entry for `import { startListener } from 'rdev-node'` in napi-vm.
//
// napi-vm resolves static ESM imports to JavaScript sources only, so the
// generated napi-rs CommonJS loader cannot be imported directly. This tiny
// wrapper re-exports it through the VM's `require()`, which keeps the
// platform selection inside the generated loader. Under Node.js the same
// `exports` map routes `import` here and `require()` at the loader.
const native = require('rdev-node');
export const startListener = native.startListener;
export const stopListener = native.stopListener;
export const add = native.add;
